const seed = await fetch('/assets/dropline_seed.json').then(r => r.json());
const STORAGE_KEY = seed.storageKey;
const rows = seed.rows;
const columns = seed.columns;
const players = Object.fromEntries(seed.players.map(p => [p.id, p]));

const boardEl = document.getElementById('board');
const controlsEl = document.getElementById('column-controls');
const historyEl = document.getElementById('history');
const statusEl = document.getElementById('status');
const feedbackEl = document.getElementById('feedback');
const redWinsEl = document.getElementById('red-wins');
const yellowWinsEl = document.getElementById('yellow-wins');
const drawsEl = document.getElementById('draws');
const undoBtn = document.getElementById('undo-btn');
const redoBtn = document.getElementById('redo-btn');
const nextRoundBtn = document.getElementById('next-round-btn');
const resetBtn = document.getElementById('reset-btn');

let state = loadState();
let cells = [];
let controlButtons = [];

function createInitialState() {
  return { version: seed.version, board: Array(rows * columns).fill(null), currentPlayer: seed.firstStarter, roundStarter: seed.firstStarter, roundStatus: 'active', winningCells: [], history: [], redo: [], scores: { red: 0, yellow: 0, draws: 0 }, moveCounter: 0, previewColumn: null, invalidMessage: '' };
}

function loadState() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return createInitialState();
    const parsed = JSON.parse(raw);
    return { ...createInitialState(), ...parsed, scores: { ...createInitialState().scores, ...(parsed.scores || {}) }, board: Array(rows * columns).fill(null).map((_, i) => parsed.board?.[i] ?? null), history: Array.isArray(parsed.history) ? parsed.history : [], redo: Array.isArray(parsed.redo) ? parsed.redo : [], winningCells: Array.isArray(parsed.winningCells) ? parsed.winningCells : [] };
  } catch { return createInitialState(); }
}

function saveState() { localStorage.setItem(STORAGE_KEY, JSON.stringify(state)); }
function idx(row, col) { return row * columns + col; }
function cellName(row, col, value) { const r = row + 1, c = col + 1; const stateName = value ? players[value].name : 'empty'; return `Row ${r}, Column ${c}, ${stateName}`; }
function currentPlayer() { return players[state.currentPlayer]; }

function renderBoard() {
  if (!cells.length) {
    boardEl.innerHTML = '';
    for (let r = 0; r < rows; r++) for (let c = 0; c < columns; c++) {
      const btn = document.createElement('button');
      btn.type = 'button'; btn.className = 'cell'; btn.dataset.row = r; btn.dataset.col = c; btn.setAttribute('role', 'gridcell'); btn.addEventListener('click', () => dropInColumn(c));
      btn.addEventListener('focus', () => setPreview(c)); btn.addEventListener('blur', clearPreviewIfMatches);
      boardEl.appendChild(btn); cells.push(btn);
    }
  }
  cells.forEach((cell, i) => {
    const r = Math.floor(i / columns), c = i % columns, value = state.board[i];
    cell.className = `cell ${value || ''} ${state.winningCells.includes(i) ? 'winner' : ''}`.trim();
    cell.textContent = value ? players[value].marker : '';
    cell.setAttribute('aria-label', cellName(r, c, value));
    cell.dataset.state = value || 'empty';
  });
}

function renderControls() {
  if (!controlButtons.length) {
    controlsEl.innerHTML = '';
    for (let c = 0; c < columns; c++) {
      const b = document.createElement('button'); b.type = 'button'; b.textContent = `Column ${c + 1}`; b.dataset.col = c;
      b.addEventListener('click', () => dropInColumn(c));
      b.addEventListener('focus', () => setPreview(c)); b.addEventListener('blur', clearPreviewIfMatches);
      b.addEventListener('keydown', handleColumnKeydown);
      controlsEl.appendChild(b); controlButtons.push(b);
    }
  }
  controlButtons.forEach((b, c) => { b.disabled = state.roundStatus !== 'active' || getDropRow(c) === -1; b.setAttribute('aria-pressed', String(state.previewColumn === c)); });
}

function renderMeta() {
  redWinsEl.textContent = state.scores.red; yellowWinsEl.textContent = state.scores.yellow; drawsEl.textContent = state.scores.draws;
  const turn = state.roundStatus === 'active' ? `${currentPlayer().name}'s turn` : state.roundStatus === 'won' ? `${players[winnerPlayer()].name} wins the round` : 'Round drawn';
  statusEl.textContent = `${turn}. Starter: ${players[state.roundStarter].name}.`;
  feedbackEl.textContent = state.invalidMessage || '';
  undoBtn.disabled = state.history.length === 0;
  redoBtn.disabled = state.redo.length === 0;
  nextRoundBtn.disabled = state.roundStatus === 'active';
}

function renderHistory() { historyEl.innerHTML = ''; state.history.forEach(move => { const li = document.createElement('li'); li.textContent = `${move.number}. ${players[move.player].name} - Column ${move.column + 1}`; historyEl.appendChild(li); }); }

function render() { renderBoard(); renderControls(); renderMeta(); renderHistory(); saveState(); }
function setPreview(col) { state.previewColumn = col; document.body.classList.remove('preview-red', 'preview-yellow'); document.body.classList.add(`preview-${state.currentPlayer}`); }
function clearPreviewIfMatches() { state.previewColumn = null; document.body.classList.remove('preview-red', 'preview-yellow'); }
function getDropRow(col) { for (let r = rows - 1; r >= 0; r--) if (!state.board[idx(r, col)]) return r; return -1; }
function winnerPlayer() { return state.history.at(-1)?.player; }
function checkWinner(startRow, startCol) { const player = state.board[idx(startRow, startCol)]; const dirs = [[1,0],[0,1],[1,1],[1,-1]]; for (const [dr,dc] of dirs) { const line = [[startRow,startCol]]; for (const dir of [1,-1]) { let r = startRow + dr * dir, c = startCol + dc * dir; while (r >= 0 && r < rows && c >= 0 && c < columns && state.board[idx(r,c)] === player) { line.push([r,c]); r += dr * dir; c += dc * dir; } } if (line.length >= 4) return line.slice(0,4).map(([r,c]) => idx(r,c)); } return null; }
function isDraw() { return state.board.every(Boolean); }
function finalizeRound(type, winningCells = []) { state.roundStatus = type; state.winningCells = winningCells; if (type === 'won') state.scores[state.currentPlayer] += 1; else state.scores.draws += 1; }
function dropInColumn(col) { state.invalidMessage = ''; if (state.roundStatus !== 'active') return feedback('Round complete. Use Undo, Next Round, or Reset Match.'); const row = getDropRow(col); if (row === -1) return feedback('That column is full.'); const i = idx(row, col); const player = state.currentPlayer; state.board[i] = player; state.history.push({ number: state.history.length + 1, player, column: col, row }); state.redo = []; state.moveCounter += 1; const win = checkWinner(row, col); if (win) finalizeRound('won', win); else if (isDraw()) finalizeRound('draw', []); else state.currentPlayer = player === 'red' ? 'yellow' : 'red'; render(); focusColumn(col); }
function feedback(msg) { state.invalidMessage = msg; renderMeta(); }
function undo() { const move = state.history.pop(); if (!move) return; state.board[idx(move.row, move.column)] = null; state.redo.push(move); state.currentPlayer = move.player; state.invalidMessage = ''; if (state.roundStatus !== 'active') { state.roundStatus = 'active'; state.winningCells = []; state.scores[state.currentPlayer === 'red' ? 'yellow' : 'red'] -= state.history.length ? 0 : 0; if (state.scores.red < 0) state.scores.red = 0; if (state.scores.yellow < 0) state.scores.yellow = 0; if (state.scores.draws < 0) state.scores.draws = 0; } if (state.history.length === 0) { state.roundStatus = 'active'; state.winningCells = []; } else { const last = state.history.at(-1); const win = checkWinner(last.row, last.column); if (win && state.history.length >= 4) { state.roundStatus = 'won'; state.winningCells = win; } else if (isDraw()) { state.roundStatus = 'draw'; } else { state.roundStatus = 'active'; state.winningCells = []; } } render(); focusColumn(move.column); }
function redo() { const move = state.redo.pop(); if (!move) return; state.currentPlayer = move.player; state.board[idx(move.row, move.column)] = move.player; state.history.push(move); const win = checkWinner(move.row, move.column); if (win) finalizeRound('won', win); else if (isDraw()) finalizeRound('draw', []); else state.currentPlayer = move.player === 'red' ? 'yellow' : 'red'; state.invalidMessage = ''; render(); focusColumn(move.column); }
function nextRound() { if (state.roundStatus === 'active') return; state.roundStarter = state.roundStarter === 'red' ? 'yellow' : 'red'; state.currentPlayer = state.roundStarter; state.roundStatus = 'active'; state.board = Array(rows * columns).fill(null); state.history = []; state.redo = []; state.winningCells = []; state.invalidMessage = ''; render(); }
function resetMatch() { state = createInitialState(); render(); }
function focusColumn(col) { controlButtons[col]?.focus(); }
function handleColumnKeydown(e) { const col = Number(e.currentTarget.dataset.col); let next = col; if (e.key === 'ArrowLeft') next = Math.max(0, col - 1); else if (e.key === 'ArrowRight') next = Math.min(columns - 1, col + 1); else if (e.key === 'Home') next = 0; else if (e.key === 'End') next = columns - 1; else if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); dropInColumn(col); return; } else return; e.preventDefault(); controlButtons[next].focus(); }
undoBtn.addEventListener('click', undo); redoBtn.addEventListener('click', redo); nextRoundBtn.addEventListener('click', nextRound); resetBtn.addEventListener('click', resetMatch);
render();
EOF

