}

function loadState() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return createInitialState();
    const parsed = JSON.parse(raw);
    return { ...createInitialState(), ...parsed, scores: { ...createInitialState().scores, ...(parsed.scores || {}) }, board: Array(rows * columns).fill(null).map((_, i) => parsed.board?.[i] ?? null), history: Array.isArray(parsed.history) ? parsed.history : [], redo: Array.isArray(parsed.redo) ? parsed.redo : [], winningCells: Array.isArray(parsed.winningCells) ? parsed.winningCells : [] };
  } catch { return createInitialState(); }
}

function saveState() { localStorage.setItem(STORAGE_KEY, JSON.stringify(state)); }
function idx(row, col) { return row * columns + col; }
function cellName(row, col, value) { const r = row + 1, c = col + 1; const stateName = value ? players[value].name : 'empty'; return `Row ${r}, Column ${c}, ${stateName}`; }
function currentPlayer() { return players[state.currentPlayer]; }

function renderBoard() {
  if (!cells.length) {
    boardEl.innerHTML = '';
    for (let r = 0; r < rows; r++) for (let c = 0; c < columns; c++) {
      const btn = document.createElement('button');
      btn.type = 'button'; btn.className = 'cell'; btn.dataset.row = r; btn.dataset.col = c; btn.setAttribute('role', 'gridcell'); btn.addEventListener('click', () => dropInColumn(c));
      btn.addEventListener('focus', () => setPreview(c)); btn.addEventListener('blur', clearPreviewIfMatches);
      boardEl.appendChild(btn); cells.push(btn);
    }
  }
  cells.forEach((cell, i) => {
    const r = Math.floor(i / columns), c = i % columns, value = state.board[i];
    cell.className = `cell ${value || ''} ${state.winningCells.includes(i) ? 'winner' : ''}`.trim();
