function renderMeta() {
  redWinsEl.textContent = state.scores.red; yellowWinsEl.textContent = state.scores.yellow; drawsEl.textContent = state.scores.draws;
  const turn = state.roundStatus === 'active' ? `${currentPlayer().name}'s turn` : state.roundStatus === 'won' ? `${players[winnerPlayer()].name} wins the round` : 'Round drawn';
  statusEl.textContent = `${turn}. Starter: ${players[state.roundStarter].name}.`;
  feedbackEl.textContent = state.invalidMessage || '';
  undoBtn.disabled = state.history.length === 0;
  redoBtn.disabled = state.redo.length === 0;
  nextRoundBtn.disabled = state.roundStatus === 'active';
}

function renderHistory() { historyEl.innerHTML = ''; state.history.forEach(move => { const li = document.createElement('li'); li.textContent = `${move.number}. ${players[move.player].name} - Column ${move.column + 1}`; historyEl.appendChild(li); }); }

function render() { renderBoard(); renderControls(); renderMeta(); renderHistory(); saveState(); }
function setPreview(col) { state.previewColumn = col; document.body.classList.remove('preview-red', 'preview-yellow'); document.body.classList.add(`preview-${state.currentPlayer}`); }
function clearPreviewIfMatches() { state.previewColumn = null; document.body.classList.remove('preview-red', 'preview-yellow'); }
function getDropRow(col) { for (let r = rows - 1; r >= 0; r--) if (!state.board[idx(r, col)]) return r; return -1; }
