function checkWinner(startRow, startCol) { const player = state.board[idx(startRow, startCol)]; const dirs = [[1,0],[0,1],[1,1],[1,-1]]; for (const [dr,dc] of dirs) { const line = [[startRow,startCol]]; for (const dir of [1,-1]) { let r = startRow + dr * dir, c = startCol + dc * dir; while (r >= 0 && r < rows && c >= 0 && c < columns && state.board[idx(r,c)] === player) { line.push([r,c]); r += dr * dir; c += dc * dir; } } if (line.length >= 4) return line.slice(0,4).map(([r,c]) => idx(r,c)); } return null; }
