function undo() { const move = state.history.pop(); if (!move) return; state.board[idx(move.row, move.column)] = null; state.redo.push(move); state.currentPlayer = move.player; state.invalidMessage = ''; if (state.roundStatus !== 'active') { state.roundStatus = 'active'; state.winningCells = []; state.scores[state.currentPlayer === 'red' ? 'yellow' : 'red'] -= state.history.length ? 0 : 0; if (state.scores.red < 0) state.scores.red = 0; if (state.scores.yellow < 0) state.scores.yellow = 0; if (state.scores.draws < 0) state.scores.draws = 0; } if (state.history.length === 0) { state.roundStatus = 'active'; state.winningCells = []; } else { const last = state.history.at(-1); const win = checkWinner(last.row, last.column); if (win && state.history.length >= 4) { state.roundStatus = 'won'; state.winningCells = win; } else if (isDraw()) { state.roundStatus = 'draw'; } else { state.roundStatus = 'active'; state.winningCells = []; } } render(); focusColumn(move.column); }
